pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 amount, address actor, address receiver) public {
        // Keep the amount in a reasonable range for transfers
        amount = bound(amount, 1, address(c).balance > 0 ? address(c).balance : 1);
        // Ensure receiver is not address(0)
        vm.assume(receiver != address(0));
        // Ensure actor is not the owner (the owner is the deployer of setUp, which is this contract)
        vm.assume(actor != address(this));

        // Record pre-balances
        uint256 preContractBalance = address(c).balance;

        // Fund the actor and attempt the transfer
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("sendTo(address,uint256)", receiver, amount));

        // The rule: any successful sendTo reduces the contract balance by exactly the amount.
        // The correct contract only allows the owner to succeed; a non-owner call reverts.
        // The buggy contract allows anyone, so the non-owner call succeeds and the balance decreases.
        if (success) {
            assertEq(address(c).balance, preContractBalance - amount, "contract balance must decrease by amount on success");
        } else {
            assertEq(address(c).balance, preContractBalance, "contract balance must remain unchanged on failure");
        }
    }
}

