import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 amount, address receiver) public {
        vm.assume(amount > 0);
        vm.assume(receiver != address(0));
        vm.assume(receiver != address(c));

        uint256 contractBalanceBefore = address(c).balance;
        uint256 senderBalanceBefore = address(this).balance;

        vm.deal(address(this), amount);
        c.sendTo{value: amount}(receiver, amount);

        uint256 contractBalanceAfter = address(c).balance;
        uint256 senderBalanceAfter = address(this).balance;

        // Reference property: the contract's balance does not change
        // (it receives exactly the `amount` sent and immediately forwards exactly `amount` to the receiver),
        // so `contractBalanceAfter == contractBalanceBefore`.
        // The buggy version tries to forward amount*2, leaving the contract Ether-less and reverting.
        assertTrue(contractBalanceAfter == contractBalanceBefore);
    }
}

